<div class="container py-5"><div class="d-flex justify-content-between align-items-end mb-4"><div><div class="eyebrow">COMMUNITY</div><h2 class="fw-bold">Forum</h2><p class="text-secondary">Temukan diskusi dan mulai thread baru.</p></div><?php if(current_user()): ?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#threadModal">New Thread</button><?php endif; ?></div>
<div class="row g-3 mb-4"><?php foreach($categories as $c): ?><div class="col-md-4"><div class="content-card"><h5><?= e($c['name']) ?></h5><p class="small text-secondary"><?= e($c['description']) ?></p><span class="badge badge-soft"><?= (int)$c['thread_count'] ?> threads</span></div></div><?php endforeach; ?></div>
<div class="content-card"><div class="forum-list"><?php foreach($threads as $t): ?><a class="forum-row" href="<?= url('thread&id='.(int)$t['id']) ?>"><div class="vote-box"><strong><?= (int)$t['vote_count'] ?></strong><small>votes</small></div><div class="flex-grow-1"><h5><?= e($t['title']) ?></h5><div class="small text-secondary"><?= e($t['category_name']) ?> · by <?= e($t['username']) ?> · <?= (int)$t['reply_count'] ?> replies</div></div></a><?php endforeach; ?></div></div>
</div>
<?php if(current_user()): ?><div class="modal fade" id="threadModal"><div class="modal-dialog"><div class="modal-content app-modal"><div class="modal-header"><h5>New Thread</h5><button class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><form method="post"><div class="modal-body"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create_thread"><label class="form-label">Category</label><select name="category_id" class="form-select mb-3"><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select><input name="title" class="form-control mb-3" placeholder="Thread title" required><textarea name="body" class="form-control" rows="6" placeholder="Write your discussion..." required></textarea></div><div class="modal-footer"><button class="btn btn-primary">Create</button></div></form></div></div></div><?php endif; ?>
